#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"
INDEX="$APP/index.html"
[[ -f "$INDEX" ]] || { echo "ERROR: index.html not found. Run this from ~/workspace."; exit 1; }
PATCH_DIR="$APP/.memeflow-patches/plans-billing-clean-v1"
mkdir -p "$PATCH_DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$PATCH_DIR/index.html.$STAMP.bak"
WORK="$PATCH_DIR/index.html.$STAMP.work"
PYTMP="$PATCH_DIR/plans_billing_v1_$STAMP.py"
cp "$INDEX" "$BACKUP"
cp "$INDEX" "$WORK"
rollback() {
  cp "$BACKUP" "$INDEX" 2>/dev/null || true
  rm -f "$WORK" "$PYTMP"
}
trap 'echo "ERROR: PLANS & BILLING CLEAN V1 failed; restoring exact pre-install index.html."; rollback' ERR
printf '%s' '' | base64 -d > "$PYTMP"
python3 -S "$PYTMP" "$WORK"
cp "$WORK" "$INDEX"
rm -f "$WORK" "$PYTMP"
cat > "$PATCH_DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
BACKUP=$BACKUP
EOF
trap - ERR
echo
echo "OK: PLANS & BILLING CLEAN V1 installed cleanly."
echo "Design: compact current plan, cleaner Free card, premium Pro card, consolidated LIVE lock."
echo "Architecture: one #billing CSS owner; billing JS/IDs/endpoints preserved."
echo "Now Stop -> Run, then hard-refresh Safari."
